// Only events ingested since the last run (see tools/build.py)
let CowrieNew = Cowrie_CL | where ingestion_time() > ago(1h);
CowrieNew
| where (eventid =~ "cowrie.command.input" and input contains "authorized_keys") and input matches regex ">>?|\\b(tee|cp|mv|chattr|sed\\s+-i)\\b"
